class Solution { public: vector<vector<int>> restoreMatrix(vector<int>& rowSum,vector<int>& colSum){vector<vector<int>> matrix(rowSum.size(),vector<int>(colSum.size()));int row=0,col=0;while(row<(int)rowSum.size()&&col<(int)colSum.size()){int value=min(rowSum[row],colSum[col]);matrix[row][col]=value;rowSum[row]-=value;colSum[col]-=value;if(!rowSum[row])++row;if(!colSum[col])++col;}return matrix;} };
